+/** Picks `ko` or `en` from an Accept-Language value (q-values, region tags); `fallback` if neither is listed. */
+export function pickLanguage(header, fallback = "en") {
+  if (typeof header !== "string") return fallback;
+  const ranked = [];
+  header.split(",").forEach((part, index) => {
+    const [tag, ...attrs] = part.trim().split(";");
+    const base = tag.trim().toLowerCase().split("-")[0];
+    if (base !== "ko" && base !== "en") return;
+    const qAttr = attrs.map((a) => a.trim()).find((a) => /^q=/i.test(a));
+    const q = qAttr ? Number(qAttr.slice(2)) : 1;
+    if (Number.isFinite(q) && q > 0) ranked.push({ base, q, index });
+  });
+  ranked.sort((a, b) => b.q - a.q || a.index - b.index);
+  return ranked.length ? ranked[0].base : fallback;
+}
